// Preserves titles, tags (TAGS attr) and dates (ADD_DATE, unix seconds).
import { parse } from 'node-html-parser';
import { isValidHttpUrl } from './normalize.js';

function escapeHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
